import {writeFileSync} from 'node:fs';
const cases=['','Zg==','Zm8=','Zm9v','_w','/w','-___','+///','Y Q\n==','Y!Q==','YQ=ignored','Y','YQ','YQ===','====','YW😃Jj'];
for(const c of [0,1,9,10,32,61,65,127,128,255,256,0x141,0x13d,0x3ff,0xd800,0xdc00,0xffff])for(const position of [0,1,2,3])cases.push('YWJj'.slice(0,position)+String.fromCharCode(c)+'YWJj'.slice(position));
const result=cases.map(text=>({text,base64:Buffer.from(text,'base64').toString('hex'),base64url:Buffer.from(text,'base64url').toString('hex'),size:Buffer.byteLength(text,'base64'),urlSize:Buffer.byteLength(text,'base64url')}));writeFileSync(process.argv[2],JSON.stringify(result,null,2)+'\n');console.log(result.length+' ACTUAL BASE64 ORACLES');

